import { useState, useEffect } from 'react';
import axios from 'axios';

const Category = () => {
  const [categories, setCategories] = useState([]);
  const [name, setName] = useState('');
  const [image, setImage] = useState(null);

  // Fetch categories from backend
  useEffect(() => {
    fetchCategories();
  }, []);

  const fetchCategories = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/users/allcategories');
      setCategories(response.data);
    } catch (error) {
      console.error("Error fetching categories:", error);
    }
  };

  const handleAddCategory = async (e) => {
    e.preventDefault();

    const formData = new FormData();
    formData.append("name", name);
    formData.append("image", image);

    try {
      const response = await axios.post('http://localhost:5000/api/users/addcategory', formData, {
        headers: {
          "Content-Type": "multipart/form-data"
        }
      });

      console.log("Category added:", response.data);
      setName('');
      setImage(null);
      fetchCategories();
    } catch (error) {
      console.error("Error adding category:", error);
    }
  };

  return (
    <div style={{ padding: "30px",ju }}>
      <h1>Categories</h1>

      {/* Add Category Form */}
      <form onSubmit={handleAddCategory} style={{ marginBottom: "20px" }} encType="multipart/form-data">
        <input
          type="text"
          placeholder="Enter Category Name"
          value={name}
          onChange={(e) => setName(e.target.value)}
          required
          style={{ padding: "10px", marginRight: "10px", width: "250px" }}
        />
        <input
          type="file"
          accept="image/*"
          onChange={(e) => setImage(e.target.files[0])}
          required
          style={{ padding: "10px", marginRight: "10px" }}
        />
        <button type="submit" style={{ padding: "10px 20px" }}>Add Category</button>
      </form>

      {/* Category Cards */}
      <div style={{ display: "flex", flexWrap: "wrap", gap: "20px" }}>
        {categories.map((cat) => (
          <div
            key={cat._id}
            style={{
              width: "200px",
              border: "1px solid #ccc",
              borderRadius: "8px",
              padding: "10px",
              textAlign: "center",
              backgroundColor: "#f9f9f9",
              boxShadow: "0 4px 8px rgba(0, 0, 0, 0.1)",
              height: "180px",
            }}
          >
            <img
              src={`http://localhost:5000/uploads/${cat.image}`}
              alt={cat.name}
              style={{ width: "100%", height: "120px", objectFit: "cover", borderRadius: "6px" }}
            />
            <h4 style={{ marginTop: "10px" }}>{cat.name}</h4>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Category;
